#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;

    int ans = 3;

    while (n--) {
        int k;
        cin >> k;

        if (ans == k) {
            cout << "NO";
            return 0;
        }

        ans = 6 - ans - k;
    }

    cout << "YES";
    return 0;
}

